//! `ATTRIBUTION.md`, generated from `data/sources.toml`.

use std::fmt::Write;

use crate::sources::Sources;

pub fn render_attribution(sources: &Sources) -> String {
    let mut s = String::new();
    s.push_str("# Attribution\n\n");
    s.push_str(
        "<!-- Generated by `hhmc attribution` from data/sources.toml. Do not edit by hand. -->\n\n",
    );
    s.push_str(
        "This world is generated from the open datasets below. Each is used under the \
         license given; the attribution text is reproduced as required by its publisher.\n\n",
    );
    for src in &sources.sources {
        let _ = writeln!(s, "## {}\n", src.title);
        let _ = writeln!(s, "- Attribution: {}", src.attribution);
        let _ = writeln!(s, "- Publisher: {}", src.publisher);
        let _ = writeln!(s, "- License: [{}]({})", src.license, src.license_url);
        let _ = writeln!(s, "- Source: <{}>", src.landing_url);
        if let Some(r) = &src.retrieved {
            let _ = writeln!(s, "- Retrieved: {r}");
        }
        let _ = writeln!(s, "- Used for: {}", src.used_for);
        s.push('\n');
    }
    s.push_str(
        "Not an official Minecraft product. Not approved by or associated with Mojang or Microsoft.\n",
    );
    s
}
